Input: {"question": "When was Empress Borjigit born?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0305-724339ddbf08:d00", "start": 0, "end": 174, "text": "Empress Dowager Xiaozhuang Empress Xiaozhuangwen (28 March 1613 – 27 January 1688), of the Khorchin Mongol Borjigit clan, personal name Bumbutai, was a consort of Hong Taiji."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0305-724339ddbf08:d00", "start": 175, "end": 203, "text": "She was 21 years his junior."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0305-724339ddbf08:d00", "start": 204, "end": 424, "text": "As Empress Dowager and Grand Empress Dowager during the reigns of her son and grandson respectively, she had significant influence in the Qing imperial court and was highly respected for her political wisdom and insight."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0305-724339ddbf08:d00", "start": 425, "end": 540, "text": "Although she never held the rank of Empress during Hong Taiji's reign, she was posthumously honoured as an empress."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0305-724339ddbf08:d00", "start": 541, "end": 619, "text": "The future Empress Xiaozhuangwen was born on the eighth day of the intercalary"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0305-724339ddbf08:d01", "start": 0, "end": 157, "text": "Empress Xiaoduanwen Empress Xiaoduanwen (31 May 1599 – 28 May 1649), of the Khorchin Mongol Borjigit clan, personal name Jerjer, was a consort of Hong Taiji."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0305-724339ddbf08:d01", "start": 158, "end": 189, "text": "She was seven years his junior."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0305-724339ddbf08:d01", "start": 190, "end": 396, "text": "The future Empress Xiaoduanwen was born on the eighth day of the intercalary fourth lunar month in the 27th year of the reign of the Wanli Emperor, which translates to 31 May 1599 in the Gregorian calendar."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0305-724339ddbf08:d01", "start": 397, "end": 483, "text": "On 28 May 1614, Lady Borjigit married Hong Taiji and became one of his multiple wives."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0305-724339ddbf08:d01", "start": 484, "end": 574, "text": "In 1623, Hong Taiji divorced his second primary consort, and elevated Lady Borjigit to the"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0305-724339ddbf08:d02", "start": 0, "end": 118, "text": "marriages, so the emperor had to choose a Borjigit woman to be his empress consort in order to keep up with tradition."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0305-724339ddbf08:d02", "start": 119, "end": 237, "text": "The Shunzhi Emperor died on 5 February 1661 and was succeeded by his third son, Xuanye, who was born to Lady Tunggiya."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0305-724339ddbf08:d02", "start": 238, "end": 399, "text": "Xuanye was enthroned as the Kangxi Emperor, while Lady Borjigit, as the empress consort of the previous emperor, was granted the title \"Empress Dowager Renxian\"."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0305-724339ddbf08:d02", "start": 400, "end": 511, "text": "She died on 7 January 1718 and was interred in a separate tomb in the Xiao Mausoleum of the Eastern Qing tombs."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0305-724339ddbf08:d02", "start": 512, "end": 574, "text": "Empress Xiaohuizhang Empress Xiaohuizhang (5 November 1641 – 7"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0305-724339ddbf08:d03", "start": 0, "end": 238, "text": "longest-reigning Empress Dowager in Qing history Sunday , 26 June 2022 , 0:00 Lauralee Swann China , Empress Xiaohuizhang , The Royal Women 0 ( public domain ) Empress Xiaohuizhang was the second of the four empresses of Emperor Shunzhi ."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0305-724339ddbf08:d03", "start": 239, "end": 276, "text": "She became Empress at the age of 13 ."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0305-724339ddbf08:d03", "start": 277, "end": 398, "text": "She became Empress Dowager at the age of 21 , and she would become the longest-reigning Empress Dowager in Qing history ."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0305-724339ddbf08:d03", "start": 399, "end": 494, "text": "[ 1 ] Yet , her enduring legacy was that she was the object of filial piety to Emperor Kangxi ."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0305-724339ddbf08:d03", "start": 495, "end": 526, "text": "While she did not give birth to"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0305-724339ddbf08:d04", "start": 0, "end": 1, "text": "."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0305-724339ddbf08:d04", "start": 2, "end": 158, "text": "In 1903 , Cixi allowed a young aristocratic photographer named Yu Xunling , a brother of Yu Deling , to take elaborately staged shots of her and her court ."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0305-724339ddbf08:d04", "start": 159, "end": 253, "text": "They were designed to convey imperial authority , aesthetic refinement , and religious piety ."}, "D5S4": {"document_number": 5, "doc_id": "ramdocs-0305-724339ddbf08:d04", "start": 254, "end": 507, "text": "As the only photographic series taken of Cixi – the supreme leader of China for more than 45 years – it represents a unique convergence of Qing court pictorial traditions , modern photographic techniques , and Western standards of artistic portraiture ."}, "D5S5": {"document_number": 5, "doc_id": "ramdocs-0305-724339ddbf08:d04", "start": 508, "end": 572, "text": "The rare glass plates have been blown up into full-size images ,"}}, "original_cards": [{"doc_id": "ramdocs-0305-724339ddbf08:d00", "card_id": "ramdocs-0305-724339ddbf08:d00:c0", "entity": "Empress Xiaozhuangwen", "scope": "Birth date", "claim": "Empress Xiaozhuangwen (28 March 1613 – 27 January 1688), of the Khorchin Mongol Borjigit clan, was born on 28 March 1613.", "answer": "28 March 1613", "quote": "Empress Dowager Xiaozhuang Empress Xiaozhuangwen (28 March 1613 – 27 January 1688), of the Khorchin Mongol Borjigit clan, personal name Bumbutai, was a consort of Hong Taiji.", "original_document_number": 1}, {"doc_id": "ramdocs-0305-724339ddbf08:d01", "card_id": "ramdocs-0305-724339ddbf08:d01:c0", "entity": "Empress Xiaoduanwen", "scope": "Birth date", "claim": "Empress Xiaoduanwen was born on 31 May 1599.", "answer": "31 May 1599", "quote": "Empress Xiaoduanwen Empress Xiaoduanwen (31 May 1599 – 28 May 1649), of the Khorchin Mongol Borjigit clan, personal name Jerjer, was a consort of Hong Taiji. She was seven years his junior. The future Empress Xiaoduanwen was born on the eighth day of the intercalary fourth lunar month in the 27th year of the reign of the Wanli Emperor, which translates to 31 May 1599 in the Gregorian calendar.", "original_document_number": 2}], "current_answers": ["28 March 1613", "31 May 1599"], "candidate_answers": [{"candidate_id": "R0", "answer": "28 March 1613", "origin": "initial"}, {"candidate_id": "R1", "answer": "31 May 1599", "origin": "initial"}]}

